1	import { readState, writeState } from './storage';
2	export async function processJob(id: string, options: { gate?: () => Promise<void>; failAfterEffect?: boolean } = {}) {
3	  const before = readState();
4	  if (before.jobs[id]?.status === 'complete') return;
5	  if (!before.jobs[id]) throw new Error('unknown job');
6	  if (options.gate) await options.gate();
7	  const state = readState();
8	  state.effects.push({ id, cents: state.jobs[id].cents });
9	  state.jobs[id].attempts++;
10	  writeState(state);
11	  if (options.failAfterEffect) throw new Error('injected worker interruption after effect');
12	  state.jobs[id].status = 'complete';
13	  writeState(state);
14	}
15	export function startService() {
16	  return Bun.serve({ hostname: '127.0.0.1', port: 0, async fetch(request) {
17	    if (new URL(request.url).pathname !== '/events' || request.method !== 'POST') return new Response('not found', { status: 404 });
18	    if (request.headers.get('Authorization') !== 'Bearer fixture-local-only') return new Response('unauthorized', { status: 401 });
19	    let event;
20	    try { event = await request.json(); } catch { return new Response('invalid JSON', { status: 400 }); }
21	    if (!/^[a-z][a-z0-9-]*$/.test(event?.id) || !Number.isSafeInteger(event?.cents) || event.cents <= 0) return new Response('invalid event', { status: 422 });
22	    const state = readState();
23	    if (!state.jobs[event.id]) state.jobs[event.id] = { cents: event.cents, status: 'pending', attempts: 0 };
24	    writeState(state);
25	    return Response.json({ accepted: event.id }, { status: 202 });
26	  }});
27	}
